// =============================================================================
// gcd — 16-bit greatest-common-divisor accelerator (Euclid, subtract-and-swap)
// CBflow open-source spec-to-GDS pilot (project opensky, sky130hd), phase P3.
// Spec: ../spec/gcd.spec.yaml; registers: ../spec/gcd_regs.rdl — the register
// block gcd_regs (+ gcd_regs_pkg) is generated by the RTL_SPEC flow
// (PeakRDL regblock, APB4).
//
// Two ways to use the engine:
//   stream  valid/ready request {a,b} -> response gcd(a,b) (as P0-P2)
//   queue   software pushes jobs through JOB_DATA into the job SRAM, pulses
//           CTRL.start; the engine fetches job i from the job SRAM (read port),
//           computes and writes the result into the result SRAM (port 0) at
//           index i; STATUS.irq when the queue is done. Results are read back
//           through RES_ADDR / RES_DATA (result SRAM read port).
// Memories (sky130_sram_1kbyte_1rw1r_32x256_8, 256 x 32, port 0 rw, port 1 r):
//   u_sram_job  job queue      port 0 <- APB pushes,   port 1 -> engine fetch
//   u_sram_res  result buffer  port 0 <- engine write, port 1 -> APB RES_DATA
// SRAM timing: address / enables registered on the rising edge, data valid
// before the next rising edge (one-cycle read latency).
// =============================================================================
module gcd
    import gcd_regs_pkg::*;
(
    input  wire        clk,
    input  wire        reset,
    // stream request: two 16-bit operands {a, b}
    input  wire        req_val,
    output wire        req_rdy,
    input  wire [31:0] req_msg,
    // stream response: gcd(a, b)
    output wire        resp_val,
    input  wire        resp_rdy,
    output wire [15:0] resp_msg,
    // APB4 register interface
    input  wire        s_apb_psel,
    input  wire        s_apb_penable,
    input  wire        s_apb_pwrite,
    input  wire [2:0]  s_apb_pprot,
    input  wire [5:0]  s_apb_paddr,
    input  wire [31:0] s_apb_pwdata,
    input  wire [3:0]  s_apb_pstrb,
    output wire        s_apb_pready,
    output wire [31:0] s_apb_prdata,
    output wire        s_apb_pslverr,
    // interrupt (STATUS.irq & CTRL.irq_en)
    output wire        irq
);
    // ── registers ───────────────────────────────────────────────────────
    gcd_regs__in_t  hwif_in;
    gcd_regs__out_t hwif_out;

    gcd_regs u_regs (
        .clk(clk), .rst(reset),
        .s_apb_psel(s_apb_psel), .s_apb_penable(s_apb_penable), .s_apb_pwrite(s_apb_pwrite),
        .s_apb_pprot(s_apb_pprot), .s_apb_paddr(s_apb_paddr), .s_apb_pwdata(s_apb_pwdata),
        .s_apb_pstrb(s_apb_pstrb), .s_apb_pready(s_apb_pready), .s_apb_prdata(s_apb_prdata),
        .s_apb_pslverr(s_apb_pslverr),
        .hwif_in(hwif_in), .hwif_out(hwif_out)
    );

    // ── engine ──────────────────────────────────────────────────────────
    typedef enum logic [2:0] {
        S_IDLE,     // wait for a stream request or CTRL.start
        S_FETCH,    // queue: job SRAM read of job_idx issued
        S_LOAD,     // queue: job data valid -> operands
        S_CALC,     // subtract-and-swap until b == 0
        S_RESP,     // stream: hold the response until resp_rdy
        S_WRITE     // queue: result SRAM write of job_idx
    } state_t;

    state_t      state;
    logic        q_mode;            // the current operation comes from the queue
    logic [15:0] a, b;
    logic [8:0]  job_cnt;           // jobs loaded (JOB_COUNT)
    logic [7:0]  job_idx;           // queue: job being processed
    logic [8:0]  res_cnt;           // queue: results written (RES_COUNT)
    logic [15:0] last_result, op_count;
    logic        push_d;            // JOB_DATA written last cycle -> push it

    // job SRAM ports
    logic        job_wr_en;
    logic [7:0]  job_wr_addr;
    logic [31:0] job_wr_data;
    logic [31:0] job_rd_data;
    // result SRAM ports
    logic [31:0] res_rd_data;

    wire a_lt_b    = (a < b);
    wire b_zero    = (b == 16'd0);
    // CTRL.start is a one-cycle pulse: a start written while the engine is
    // busy (stream operation, response held) is kept pending until the engine
    // is idle — then the queue takes priority over stream requests
    logic start_pend;
    wire start_q   = (hwif_out.CTRL.start.value || start_pend) && (job_cnt != 9'd0);
    wire req_fire  = req_val  && req_rdy;
    wire resp_fire = resp_val && resp_rdy;
    wire q_last    = ({1'b0, job_idx} == job_cnt - 9'd1);
    wire q_done    = (state == S_WRITE) && q_last;

    always_ff @(posedge clk) begin
        if (reset) begin
            state   <= S_IDLE;
            q_mode  <= 1'b0;
            a       <= 16'd0;
            b       <= 16'd0;
            job_idx <= 8'd0;
            res_cnt <= 9'd0;
        end else begin
            case (state)
                S_IDLE:
                    if (start_q) begin
                        q_mode  <= 1'b1;
                        job_idx <= 8'd0;
                        res_cnt <= 9'd0;
                        state   <= S_FETCH;
                    end else if (req_fire) begin
                        q_mode <= 1'b0;
                        a      <= req_msg[31:16];
                        b      <= req_msg[15:0];
                        state  <= S_CALC;
                    end
                S_FETCH: state <= S_LOAD;
                S_LOAD: begin
                    a     <= job_rd_data[31:16];
                    b     <= job_rd_data[15:0];
                    state <= S_CALC;
                end
                S_CALC:
                    if (a_lt_b) begin
                        a <= b;                 // swap so a >= b
                        b <= a;
                    end else if (!b_zero) begin
                        a <= a - b;
                    end else begin
                        state <= q_mode ? S_WRITE : S_RESP;
                    end
                S_RESP: if (resp_rdy) state <= S_IDLE;
                S_WRITE: begin
                    res_cnt <= res_cnt + 9'd1;
                    if (q_last) begin
                        q_mode <= 1'b0;
                        state  <= S_IDLE;
                    end else begin
                        job_idx <= job_idx + 8'd1;
                        state   <= S_FETCH;
                    end
                end
                default: state <= S_IDLE;
            endcase
            if (hwif_out.CTRL.q_clr.value && state == S_IDLE) res_cnt <= 9'd0;
        end
    end

    // pending start: set by a start pulse outside S_IDLE, consumed in S_IDLE
    // (the queue starts, or an empty queue drops it)
    always_ff @(posedge clk) begin
        if (reset)                           start_pend <= 1'b0;
        else if (state == S_IDLE)            start_pend <= 1'b0;
        else if (hwif_out.CTRL.start.value)  start_pend <= 1'b1;
    end

    assign req_rdy  = (state == S_IDLE) && !start_q;
    assign resp_val = (state == S_RESP);
    assign resp_msg = a;

    // job queue: a JOB_DATA write is pushed the cycle after (the register
    // holds the new value then); full at 256 jobs (further pushes dropped)
    always_ff @(posedge clk) begin
        if (reset) begin
            push_d  <= 1'b0;
            job_cnt <= 9'd0;
        end else begin
            push_d <= hwif_out.JOB_DATA.data.swmod;
            if (hwif_out.CTRL.q_clr.value && state == S_IDLE) job_cnt <= 9'd0;
            else if (push_d && !job_cnt[8])                   job_cnt <= job_cnt + 9'd1;
        end
    end
    assign job_wr_en   = push_d && !job_cnt[8];
    assign job_wr_addr = job_cnt[7:0];
    assign job_wr_data = hwif_out.JOB_DATA.data.value;

    // status / counters
    wire done_op = resp_fire || (state == S_WRITE);
    always_ff @(posedge clk) begin
        if (reset) begin
            last_result <= 16'd0;
            op_count    <= 16'd0;
        end else begin
            if (done_op) last_result <= a;
            if (hwif_out.CTRL.cnt_clr.value) op_count <= 16'd0;
            else if (done_op)                op_count <= op_count + 16'd1;
        end
    end

    assign hwif_in.STATUS.busy.next     = (state != S_IDLE) && (state != S_RESP);
    assign hwif_in.STATUS.done.next     = (state == S_RESP);
    assign hwif_in.STATUS.irq.hwset     = resp_fire || q_done;
    assign hwif_in.STATUS.q_busy.next   = q_mode;
    assign hwif_in.RESULT.value.next    = last_result;
    assign hwif_in.OPCOUNT.count.next   = op_count;
    assign hwif_in.JOB_COUNT.count.next = job_cnt;
    assign hwif_in.RES_DATA.data.next   = res_rd_data[15:0];
    assign hwif_in.RES_COUNT.count.next = res_cnt;
    assign irq = hwif_out.STATUS.irq.value & hwif_out.CTRL.irq_en.value;

    // ── memories ────────────────────────────────────────────────────────
    // job queue: port 0 writes pushed jobs, port 1 reads job_idx in S_FETCH
    sky130_sram_1kbyte_1rw1r_32x256_8 u_sram_job (
        .clk0(clk), .csb0(~job_wr_en), .web0(1'b0), .wmask0(4'hF),
        .addr0(job_wr_addr), .din0(job_wr_data), .dout0(),
        .clk1(clk), .csb1(~(state == S_FETCH)), .addr1(job_idx), .dout1(job_rd_data)
    );

    // result buffer: port 0 writes results in S_WRITE, port 1 reads RES_ADDR
    sky130_sram_1kbyte_1rw1r_32x256_8 u_sram_res (
        .clk0(clk), .csb0(~(state == S_WRITE)), .web0(1'b0), .wmask0(4'hF),
        .addr0(job_idx), .din0({16'd0, a}), .dout0(),
        .clk1(clk), .csb1(1'b0), .addr1(hwif_out.RES_ADDR.addr.value), .dout1(res_rd_data)
    );
endmodule
